use super::*;
fn signature(words:&[String])->std::collections::BTreeMap<usize,Option<[u64;6]>>{
 let s=format!("<doc><page width='595' height='842'>{}</page></doc>",words.join(""));let d=Html::parse_document(&s);let p=d.select(&Selector::parse("page").unwrap()).next().unwrap();let(_,w,_,_,_,_,styles,_,_,_,_,_,flows , _, _)=page_words_with_styles(p,595.,842.,None);assert_eq!(w.len(),flows.len());styles.iter().zip(flows).map(|(style,f)|{let font=style.as_ref().unwrap().iter().next().unwrap().0;let f=f.map(|n|[n.start.to_bits(),n.baseline.to_bits(),n.end.to_bits(),n.leading.to_bits(),n.trailing.to_bits(),n.prefix.to_bits()]);(font,f)}).collect()
}
fn word(font:usize,flow:&str)->String{format!("<word xmin='10' ymin='93' xmax='18' ymax='102' data-wmode='0' data-native-axis='right' data-native-styles='{font}:4020000000000000' {flow}>任意</word>")}
fn flow(y:&str)->String{format!("data-native-flow-start='10' data-native-flow-baseline='{y}' data-native-flow-end='18' data-native-flow-leading='8' data-native-flow-trailing='0' data-native-flow-prefix='0'")}
#[test]fn source_flow_stays_with_its_own_exact_bbox_and_text_tie_through_canonical_sort(){let words=vec![word(11,&flow("100.00000000001")),word(27,&flow("101"))];let forward=signature(&words);let mut reverse=words;reverse.reverse();assert_eq!(forward,signature(&reverse));assert_eq!(forward[&11],Some([10f64.to_bits(),100.00000000001f64.to_bits(),18f64.to_bits(),8f64.to_bits(),0f64.to_bits(),0f64.to_bits()]));assert_eq!(forward[&27],Some([10f64.to_bits(),101f64.to_bits(),18f64.to_bits(),8f64.to_bits(),0f64.to_bits(),0f64.to_bits()]));}
#[test]fn missing_or_invalid_flow_does_not_borrow_a_duplicate_words_metadata(){let words=vec![word(1,&flow("100")),word(2,&flow("NaN")),word(3,"")];let a=signature(&words);let mut b=words;b.reverse();assert_eq!(a,signature(&b));assert!(a[&1].is_some());assert_eq!(a[&2],None);assert_eq!(a[&3],None);}
#[test]fn source_tracking_and_TJ_adjustments_stay_with_their_own_words(){let a=flow("100").replace("data-native-flow-trailing='0'","data-native-flow-trailing='-4'").replace("data-native-flow-prefix='0'","data-native-flow-prefix='3'");let b=flow("100").replace("data-native-flow-trailing='0'","data-native-flow-trailing='5'").replace("data-native-flow-prefix='0'","data-native-flow-prefix='-2'");let v=vec![word(1,&a),word(2,&b)];let first=signature(&v);let mut v=v;v.reverse();assert_eq!(first,signature(&v));assert_eq!(first[&1].unwrap()[4..],[(-4f64).to_bits(),3f64.to_bits()]);assert_eq!(first[&2].unwrap()[4..],[5f64.to_bits(),(-2f64).to_bits()]);}
